    <button id="release">Release</button>
    <canvas id="canvas" width="300" height="300"></canvas>
    <script>
        // Get elements
        const pendulum = document.getElementById('pendulum');
        const angleInput = document.getElementById('angle');
        const releaseButton = document.getElementById('release');
        const canvas = document.getElementById('canvas');
        const ctx = canvas.getContext('2d');

        // pendulum parameters
        let length = 100;
        let gravity = 9.81;
        let angle = 0;
        let velocity = 0;
        let isReleased = false;

        // simulation parameters
        let dt = 0.01;
        let simulations = [];

        // draw pendulum circle
        function drawPendulum() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            ctx.beginPath();
            ctx.arc(canvas.width / 2, canvas.height / 2, length, 0, 2 * Math.PI);
            ctx.fillStyle = 'red';
            ctx.fill();
            ctx.beginPath();
            ctx.arc(canvas.width / 2 + length * Math.sin(angle), canvas.height / 2 - length * Math.cos(angle), 10, 0, 2 * Math.PI);
            ctx.fillStyle = 'black';
            ctx.fill();
        }

        // update pendulum
        function updatePendulum() {
            if (!isReleased) {
                velocity = 0;
                angle = parseFloat(angleInput.value) * Math.PI / 180;
            } else {
                let acceleration = -gravity / length * Math.sin(angle);
                velocity += acceleration * dt;
                angle += velocity * dt;
            }

            if (Math.abs(angle) > Math.PI / 2 || Math.abs(angle) < -Math.PI / 2) {
                velocity = 0;
                angle = 0;
            }

            drawPendulum();
        }

